INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('1604', '聲寶股份有限公司', '聲寶', '電器電纜', 'listed', '君瑜投資有限公司', '彭俊彥', '桃園市龜山區大華里頂湖26-3號', '', '19620911', '19701214', '3842000000', '03607500', '384200000', 723, 805, 763, 850, -5.24, -5.29, 715, 1.7, 114, NULL, NULL, NULL, NULL, 904, 1.51, -20.0, False, True, False, '為落實深耕台灣的永續承諾，本公司斥資27億元建置台南新廠。 隨著生產基地轉移，公司積極推動人才世代交替，雖有資深同仁相 繼榮退，但也成功吸引大量優秀在地青年加入，人才結構年輕化為 平均薪資略低於業界的主因。', '公司未來將持續落實完善的留才與薪酬調整機制，並配合現有的內 部升遷管道與人才培訓資源，協助新進同仁快速成長並實現職涯晉 升，全面提升薪酬之市場競爭力，落實友善職場與在地留才之承諾。', 800422, 11.025851223345304, '11507', 90.7, 52, '1nnt8tc', NULL, NULL);
