INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('6606', '建德工業股份有限公司', '建德工業', '電機機械', 'listed', '李金旆', '黃盈璇', '雲林縣斗六市斗工九路17號', '', '19660316', '20230324', '1103037830', '35309102', '110303783', 547, 578, 579, 595, -5.53, -2.86, 63, 1.09, 114, NULL, NULL, NULL, NULL, 910, 1.58, -39.9, False, False, True, '本公司受工具機產業景氣放緩及接單受阻影響，營運面臨挑戰。惟 為維持技術傳承，仍策略性持續聘用並培育較多基層技術與儲備人 才，致非主管職平均薪資受人力結構影響低於同業。公司薪酬均合 規，並保障員工福利與調薪。', '為留任人才，我司推動四項措施：一、精進績效考核與獎酬連結； 二、提升零件自製率增進獲利；三、拓展海外與新興客戶強化接單 ；四、落實盈餘調薪與獎金共享。期能兼顧股東與員工權益，提升 薪酬競爭力並達成永續經營。', 90532, 39.73359675253515, '11507', 28.4, NULL, NULL, NULL, NULL);
