INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('3508', '位速科技股份有限公司', '位速', '其他電子業', 'otc', '廖世文', '廖世文', 'No. 26  Gaoqing Rd.Yangmei, Taoyuan County, Taiwan, R.O.C.', '03-4965000', '20010904', '20071017', '', '', '', 614, 756, 640, 775, -4.06, -2.45, 66, -1.51, 114, NULL, NULL, NULL, NULL, 975, 4.62, -37.0, False, False, True, '114年度因招募基層新進同仁拉低整體的薪資平均數。導致公司 EPS較前一年度成長(損失減少)，惟非經理人全時員工薪資平 均數衰退。', '1.本公司已於章程明訂年度盈餘提撥一定比率，作為基層員工分 派酬勞之用，確保員工能直接分享EPS成長的果實。 2.本公司依據年度營運績效及個人考績，實施結構性調薪，確保 績效優良員工的薪資具備市場競爭力。', 84050, 15.283854773890024, '11507', 2.28, 12, '5x99680', NULL, NULL);
INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('3511', '矽瑪科技股份有限公司', '矽瑪', '電子零組件業', 'otc', '黃漢州', '胡若堯', '14F., No.1351, Zhong-Zheng Rd., Taoyuan Dist., Taoyuan City 33071,TaiwanTaiwan,R.O.C.', '(03)301-0008', '20031215', '20090216', '', '', '', 824, 956, 859, 1001, -4.07, -4.5, 52, -1.18, 114, NULL, NULL, NULL, NULL, 797, 2.47, 3.4, False, False, True, '本公司114年度因約15%資深員工離退並補進新人，薪資平均 數下降主要係人員結構變動，非整體調降薪資。雖EPS較前一年 改善惟仍處虧損，依法未能提列員工分紅。公司薪酬參考科技業P 50並依職能核薪，具市場競爭力與合理性', '公司雖仍處虧損仍維持每年平均3%調薪，照顧基層同仁並穩定實 質薪資。未來將持續優化績效考核依達成結果差異化分配調薪資源 獎勵優秀人才；待營運轉盈後依法提列員工酬勞與分紅，強化留才 及獲利共享機制', 188919, 57.03076296474852, '11507', 1.53, 5, '1116167c', NULL, NULL);
