INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('6597', '立誠光電股份有限公司', '立誠', '電子零組件業', 'otc', '周萬順', '李忠義', '6 F., No. 5, Ln. 17, Sec. 3, Nanshan Rd., Luzhu Dist.,Taoyuan City , Taiwan, R.O.C.', '03-324-5050', '20110114', '20250508', '', '', '', 626, 697, 0, 0, 0.0, 0.0, 193, 2.51, 114, NULL, NULL, NULL, NULL, 797, 2.47, -21.5, False, True, False, '本公司除提供固定薪資外，另依公司章程及年度獲利情形提列員工 酬勞，並訂有嚴謹的各項績效獎金辦法。公司經營績效提升獲利增 加時，員工透過員工酬勞及績效獎金分享經營成果，故員工薪酬與 經營績效具一定關聯合理性。', '本公司114年度獲利下滑，稅後淨利由121636仟元下滑 至71333仟元，致各項變動薪酬如績效獎金、年終獎金相對 下滑。具體改善措施：1.持續提升公司經營績效2.定期檢視薪 酬制度3.強化績效連結機制4.提升員工專業能力。', 61066, 0.9055157143329258, '11507', 2.18, NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('6603', '富強鑫精密工業股份有限公司', '富強鑫', '電機機械', 'otc', '王伯壎', '王俊賢', '269, Bao Dong Road, Pi Tou Village, Guanmiao Dist.,Tainan , Taiwan, R.O.C.', '06-5950688', '19910717', '20040405', '', '', '', 583, 663, 596, 674, -2.18, -1.63, 240, 0.61, 114, NULL, NULL, NULL, NULL, 747, 1.65, -22.0, False, False, True, '本公司正積極推動人才梯隊的世代交替與經驗傳承。2025 年 因部分高年資資深同仁步入退休階段，以及新世代人才之策略性引 入，致使整體員工人數與薪資指標（總額、中位數及平均數）受結 構性影響而微幅變動。', '針對新進同仁與關鍵技術人才，本公司持續優化薪資結構與報酬制 度，以確保整體薪酬具備市場競爭力與公平性。未來將持續透過完 善的職涯發展與留才機制，與同仁共享長期穩健的營運成果。', 443027, 36.55886468858462, '11507', 4.15, 8, '13kawv1c', NULL, NULL);
