INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('6642', '富致科技股份有限公司', '富致', '電子零組件業', 'otc', '陳繼聖', '陳繼聖', 'No.111 Wu-Gung 1 Road. Wu Gu Dist.,New Taipei City, Taiwan', '02-89902113', '19991202', '20190923', '', '', '', 532, 635, 531, 679, 0.19, -6.48, 119, 2.6, 114, NULL, NULL, NULL, NULL, 797, 2.47, -33.2, False, True, False, '本公司產品皆在台灣生產，無海外生產基地，故生產線人員比重佔 全公司人員比重超過六成。所以員工薪資呈現上，會較同業在台灣 是以管理及研發為主的公司低，此因人力結構上的差異造成平均薪 資上的落差。', '公EPS獲利表現較同業為佳，惟非經理人之全時員工薪資平均數 低於同業水準。係因人力結構上的差異造成平均薪資上的落差。公 司本著根留台灣原則，故目前尚無將產線移至海外之規劃。故此人 力結構差異將持續存在。', 71671, 71.47402923654808, '11507', 2.92, NULL, NULL, NULL, NULL);
