INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('6684', '安格科技股份有限公司', '安格', '半導體業', 'otc', '羅森洲', '藍世旻', 'No. 55, Gaotie 2nd Rd., Zhubei City,Hsinchu County, Taiwan (R.O.C.)', '03-6675345', '20101021', '20210811', '', '', '', 1178, 1257, 1204, 1345, -2.16, -6.54, 60, 1.57, 114, NULL, NULL, NULL, NULL, 1400, 5.37, -15.9, False, False, True, '本公司114年度EPS雖轉虧為盈，惟認列神雋換股之一次性業 外處分利益，核心本業營收仍虧損。基於薪酬與本業績效連結，該 年除減少發放績效獎金，員工調薪除極少人員外全面暫停；因應公 司發展策略，亦進行人力結構調整。', '針對本業營運狀況及員工薪酬之平衡，本公司已規劃並執行以下措 施：1因應市場調整產品策略2恢復年度調薪，展現公司與員工共 享未來營運成果之誠意。  後續待核心本業業績與獲利回穩後，本公司將持續滾動式檢視調整', 27024, 8.45607416623189, '11507', 2.01, NULL, NULL, NULL, NULL);
