INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('7712', '博盛半導體股份有限公司', '博盛半導體', '半導體業', 'otc', '孟祥集', '孟祥集', '6F-3, No. 32, Gaotie 2nd Rd.Zhubei City, Hsinchu County 302, Taiwan', '(03)668-2068', '20140430', '20241226', '', '', '', 1091, 1271, 1364, 1614, -20.01, -21.25, 60, 5.42, 114, NULL, NULL, NULL, NULL, 1400, 5.37, -22.1, False, True, False, 'EPS與半導體的分類比較，實不符中小企業，資本額在3.26 億的IC設計公司。本公司的人力競爭也處處不如半導體企業。因 2025年EPS驟降，股東反應不佳，惟員工酬金均依規定辦理。', '2026年如公司經營進步，將會提請獎勵提案，儘量做到投資者 與員工的照顧。', 168173, 63.2874398011496, '11507', 4.95, NULL, NULL, NULL, NULL);
