INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('7747', '昕奇雲端科技股份有限公司', '昕奇雲端', '數位雲端', 'otc', '許承強', '許承強', '2F., No. 33, Ln. 76, Ruiguang Rd., Neihu Dist.,Taipei City 114 , Taiwan (R.O.C)', '02-87923677', '20171011', '20250711', '', '', '', 758, 803, 0, 0, 0.0, 0.0, 24, 4.04, 114, NULL, NULL, NULL, NULL, 872, 3.2, -13.1, False, True, False, '主要係因商業模式及人力結構與部分同業有所差異，致平均薪資受 結構性因素影響而有所落差。另本公司EPS係反映集團整體經營 成果與員工薪資統計範圍基礎不同。本公司除固定薪資外亦透過獎 金及員工酬勞等共享經營成果。', '本公司將持續參考同業薪酬水準及市場人才供需情形，定期檢討薪 酬制度與獎酬機制，並依營運成果及員工績效適時調整薪資及獎酬 ，強化人才培育、職涯發展及留才措施，提升薪酬競爭力並共享經 營成果。', 153172, 35.17005241885667, '11507', 3.41, 9, '1a2x6blvl8', NULL, NULL);
