INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('7753', '星亞視覺股份有限公司', '星亞', '光電業', 'otc', '戴呈易', '李柏龍', '8F.,NO.1,Li-hsin Rd.V,Hsinchu Science ParkHsinchu,Taiwan,R.O.C.', '03-5638966', '20210916', '20250811', '', '', '', 743, 879, 0, 0, 0.0, 0.0, 134, 4.22, 114, NULL, NULL, NULL, NULL, 882, 2.4, -15.8, False, True, False, '(1)薪資平均數略低於同業水準3仟元，係因公司人力結構直接 人員約三成，經營型態製造基層人力佔比較高。 (2)本公司114年獲利較同期增加，員工薪資平均數及中位數 均有增加，透過每年績效評估作為薪資報酬依據。', '(1)本公司新進員工薪資係參考市場行情及考量過往工作經驗及 績效等因素評定，應屬合理機制。 (2)本公司如有獲利，會依照獲利狀況發放年終獎金及員工酬勞 ，透過績效制度反映員工薪酬結果。', 60955, -22.981185954537988, '11507', 0.91, NULL, NULL, NULL, NULL);
