INSERT OR REPLACE INTO company_profiles (stock_id, name, short_name, industry, market, chairman, gm, address, phone, established, listed_date, capital, tax_id, shares_outstanding, salary_median_k, salary_mean_k, salary_median_prev_k, salary_mean_prev_k, salary_median_change_pct, salary_mean_change_pct, employee_count, eps, salary_year, salary_male_median_k, salary_female_median_k, salary_male_mean_k, salary_female_mean_k, industry_salary_avg_k, industry_avg_eps, salary_vs_industry_pct, flag_low_salary, flag_eps_high_salary_low, flag_eps_up_salary_down, salary_explanation, improvement_measures, revenue_latest, revenue_yoy_pct, revenue_period, market_cap, job_count_104, encoded_cust_no_104, job_count_linkedin, ai_insight) VALUES ('7767', '仁大資訊股份有限公司', '仁大資訊', '資訊服務業', 'otc', '林士茵', '陳宏明', '3 F., No. 216, Sec. 3, New Taipei Blvd., Xinzhuang Dist., New Taipei City 2420New Taipei City, Taiwan.', '(02)2298-2958', '19990412', '20251210', '', '', '', 523, 614, 0, 0, 0.0, 0.0, 422, 4.18, 114, NULL, NULL, NULL, NULL, 1016, 3.17, -48.5, False, True, False, '本公司每股盈餘（EPS）高於同業平均水準，惟非經理人全時員 工平均薪資仍低於同業，主要係因本公司業務以終端設備之維護與 安裝為主，相關工程師所需專業技能相對較低，且人員流動率較高 ，致整體薪資水準偏低。', '惟本公司已注意此情形，並於近兩年逐步進行薪資結構調整，惟考 量整體營運與成本配置，尚無法一次大幅提升。114年度非經理 人全時員工平均薪資已由595千元提升至614千元，顯見本公 司已持續朝改善薪酬水準之方向努力。', 322536, 127.4279186850845, '11507', 1.35, NULL, NULL, NULL, NULL);
